function renderMaterialsPage({MODEL,$,fmt,n,esc,raw,unit,factBtn,sheetBtn,heading,moneyless,revisedQuantity,foundationBalanceCard,loadComparisonHTML,foundationRebarAuditCard,FACTS}){
 const foundationMaterials=['foundation.concrete.quantity','foundation.blinding.quantity','foundation.gravel_5_10.quantity','foundation.gravel_20_40.quantity','foundation.xps.quantity','foundation.geotextile.quantity'];
 const steel=['foundation.Фм1.steel_kg_А240_8','foundation.Фм1.steel_kg_А500С_8','foundation.Фм1.steel_kg_А500С_12'];
 const rebarRows=Array.from({length:8},(_,i)=>{const ent='foundation.Фм1.rebar.'+(i+1),q=FACTS.get(ent+'.quantity');return `<tr><td class="number">${i+1}</td><td>Ø${raw(ent+'.diameter')} ${raw(ent+'.grade')}</td><td class="number">${FACTS.has(ent+'.length')?raw(ent+'.length'):'погонный расход'}</td><td class="number">${revisedQuantity(ent+'.quantity')}</td><td class="number">${raw(ent+'.unit_mass')} ${unit(FACTS.get(ent+'.unit_mass').unit)}</td><td>${factBtn(ent+'.quantity','КЖ-4')}</td></tr>`;}).join('');
 const geo=Object.fromEntries(MODEL.foundation.calculations.map(c=>[c.id.split('.').at(-1),Number(c.value)]));
 const takeoff=MODEL.foundation.steel_takeoff,concrete=geo.total_volume,blinding=geo.blinding;
 const netLayers=[['Щебень 20–40',geo.gravel20,'м³','Площадь × 0,200 м'],['Щебень 5–10',geo.gravel5,'м³','Площадь × 0,200 м'],['Геотекстиль',geo.area,'м²','Один проход под плитой'],['Армированный полиэтилен',geo.area,'м²','Один проход под плитой'],['Рулонная гидроизоляция',geo.area,'м²','Один слой под плитой']];
 $('page-materials').innerHTML=heading('02 / ФУНДАМЕНТ / РАСЧЁТНЫЙ ВАРИАНТ','Материалы фундамента без дуги','Количество по модели с прямым восточным краем. Расчётные объёмы показаны без закупочного запаса.','По новой геометрии')+
 `<div class="metric-grid">${[['БЕТОН В25',concrete,'м³','Плита и ростверки'],['ПОДГОТОВКА В10',blinding,'м³','В пределах плиты'],['АРМАТУРА',takeoff.net_mass_kg,'кг','Оценка по базовой раскладке'],['ПЛОЩАДЬ ПЛИТЫ',geo.area,'м²','Край параллельно фасаду']].map(([label,val,u,note])=>`<div class="metric"><div class="eyebrow">${label}</div><strong>${fmt(val,3)} <em>${u}</em></strong><small>${note}</small></div>`).join('')}</div>
 <div class="section-grid"><div class="card"><h3>Слои под плитой</h3><table><tbody>${netLayers.map(([name,q,u,rule])=>`<tr><td>${name}<small class="block-note">${rule}</small></td><td class="number">${fmt(q,5)} ${u}</td></tr>`).join('')}</tbody></table><p>Расчёт ограничен пятном плиты. Выпуски за край, нахлёсты полотен и заведение на стенки требуют раскладки. Для утеплителя и отмостки полный контур не задан. XPS · ${revisedQuantity('foundation.xps.quantity')}.</p>${sheetBtn('house_2',8,'КЖ-3 · сечения')}</div>
 <div class="card"><h3>Арматура по новой форме</h3><table><thead><tr><th>Поз.</th><th>Раскладка</th><th>Масса, кг</th></tr></thead><tbody>${takeoff.rows.map(r=>`<tr><td>${r.position}</td><td>${fmt(r.quantity,3)} ${unit(r.unit)}</td><td>${fmt(r.net_mass_kg,3)}</td></tr>`).join('')}</tbody></table><p>${esc(takeoff.note)}</p></div></div>
 <div class="section-grid"><div><div class="card"><h3>Материалы КЖ-4 · исходные и текущие количества</h3><div class="table-wrap"><table><thead><tr><th>Материал</th><th>Количество</th><th>Основание</th></tr></thead><tbody>${foundationMaterials.map(id=>{const f=FACTS.get(id);return `<tr><td>${esc(f.label)}</td><td class="number">${revisedQuantity(id)}</td><td>${factBtn(id)}</td></tr>`;}).join('')}</tbody></table></div><p class="tiny muted" style="margin-top:15px">Запас к бетону здесь не добавлен. Щебень показан по двум отдельным фракциям; коэффициент уплотнения 0,95 относится к сечению КЖ-3.</p></div>
 <div class="card"><h3>Сталь Фм 1 · с надбавкой 5 %</h3><table><thead><tr><th>Арматура</th><th>Масса</th><th>Источник</th></tr></thead><tbody>${steel.map((id,i)=>`<tr><td>${['А240 · Ø8','А500С · Ø8','А500С · Ø12'][i]}</td><td class="number">${revisedQuantity(id)}</td><td>${factBtn(id)}</td></tr>`).join('')}<tr><td><b>Всего</b></td><td class="number">${revisedQuantity('foundation.Фм1.steel_kg_total')}</td><td>${factBtn('foundation.Фм1.steel_kg_total')}</td></tr></tbody></table><div class="formula">${fmt(takeoff.net_mass_kg)} × 1,05 = ${fmt(MODEL.foundation.quantity_changes['foundation.Фм1.steel_kg_total'].current)} кг</div><p>Зачёркнуты итоги исходной ведомости с её надбавкой 5 %. Новые массы получены из текущих длин и количества деталей с той же надбавкой.</p></div></div>
 <div><div class="card"><h3>Бетон и цемент — разные количества</h3><p>Для нового контура учтены ${fmt(concrete)} м³ В25 и ${fmt(blinding)} м³ В10 в пятне плиты. Расход цемента на м³ смеси в этих листах не найден. Без рецептуры нельзя перевести это в точное количество мешков.</p><div class="callout"><b>Расход цемента по проекту не определён</b>Нужны составы В25 W6 F150 и В10. Калькулятор ниже считает только введённый сценарий; справочных норм по умолчанию нет.</div><div class="input-grid"><label>В25: цемент, кг/м³<input id="cement-b25" type="number" min="0" max="1000" step="0.1" placeholder="из рецептуры"></label><label>В10: цемент, кг/м³<input id="cement-b10" type="number" min="0" max="1000" step="0.1" placeholder="из рецептуры"></label></div><div class="calc-result" id="cement-result">Не задано<small>Проектный расход цемента отсутствует.</small></div><div class="formula">m = ${fmt(concrete)} × C<sub>В25</sub> + ${fmt(blinding)} × C<sub>В10</sub>, кг</div></div>
 <div class="card"><h3>Крыльца Крм 1 и Крм 2</h3><p>Крм 1 у входа можно добавить к итогу отдельно. Крм 2 на КЖ-5 имеет дугообразные ступени. Для прямого края требуется новый узел площадки и ступеней. Для снятого изделия приведён пересчёт КЖ-6.</p><table><thead><tr><th>Элемент</th><th>В25, м³</th><th>Сталь, кг</th></tr></thead><tbody>${[1,2].map(i=>`<tr><td>${factBtn(`porch.Крм${i}.concrete.quantity`,'Крм '+i)}</td><td class="number">${i===2?revisedQuantity('porch.Крм2.concrete.quantity'):raw('porch.Крм1.concrete.quantity')}</td><td class="number">${i===2?revisedQuantity('porch.Крм2.steel_kg_total'):raw('porch.Крм1.steel_kg_total')}</td></tr>`).join('')}</tbody></table><label class="control"><input type="checkbox" id="include-porches"> Добавить входное крыльцо Крм 1</label><div id="porch-total" class="formula"></div></div>
 <div class="card"><h3>Плита и ростверки Фм 1</h3><div class="formula"><del>246,4 × 0,300 = 73,92 м³</del><br><strong class="updated">${fmt(geo.area)} × 0,300 = ${fmt(geo.slab_volume,8)} м³</strong><br>Ростверки над плитой · ${fmt(geo.plinth_volume,8)} м³<br>Всего В25 · ${revisedQuantity('foundation.concrete.quantity')}</div><p>Площадь открытых площадок до наружных граней ростверков · ${revisedQuantity('building.terrace_porch_area')}. В площадь плитки входят отдельные поправки на ступени и уклон.</p>${sheetBtn('house_1',8,'АР-7 · экспликация площадок')}</div></div></div>
 <div class="card"><div class="page-heading"><div><h3>Восемь позиций КЖ-4 · пересчёт количества</h3><p>Погонные метры и штуки сохранены разными единицами. Длина — заготовка из спецификации.</p></div></div><div class="table-wrap"><table><thead><tr><th>Поз.</th><th>Диаметр / класс</th><th>Длина, мм</th><th>Количество</th><th>Масса единицы</th><th>Источник</th></tr></thead><tbody>${rebarRows}</tbody></table></div>${sheetBtn('house_2',9,'КЖ-4 · исходная ведомость и формы деталей')}</div>`;
 const recalc=()=>{const a=$('cement-b25'),b=$('cement-b10');if(a.value===''||b.value===''||!a.validity.valid||!b.validity.valid){$('cement-result').innerHTML='Не задано<small>Введите обе дозировки из рецептур.</small>';return;}const result=concrete*+a.value+blinding*+b.value;$('cement-result').innerHTML=`${fmt(result,3)} кг<small>Сценарий пользователя · не проектный расход. Только Фм 1 и подготовка, без Крм 1/2.</small>`;};$('page-materials').querySelector('.metric-grid').insertAdjacentHTML('afterend',foundationBalanceCard()+loadComparisonHTML());$('cement-b25').oninput=recalc;$('cement-b10').oninput=recalc;
 $('page-materials').insertAdjacentHTML('beforeend',foundationRebarAuditCard());
 const updatePorches=()=>{const include=$('include-porches').checked;
  const porchSum=key=>include?n(`porch.Крм1.${key}`):0;
  $('porch-total').innerHTML=`В25 · ${fmt(concrete+porchSum('concrete.quantity'))} м³<br>В10 под плитой · ${fmt(blinding)} м³<br>Сталь с дополнительными 5 % · ${fmt(+MODEL.foundation.quantity_changes['foundation.Фм1.steel_kg_total'].current+porchSum('steel_kg_total'),4)} кг${include?'<br><small>К расчёту Фм 1 добавлены исходные количества КЖ-6 для входного крыльца.</small>':''}`;
 };$('include-porches').onchange=updatePorches;updatePorches();
}

export { renderMaterialsPage };
